private static bool HasScheduleCheckingContent(SIM_ScheduleChecking obj)
{
    if (obj == null)
        return false;
    return (obj.TheoryQuantity > 0 || obj.PracticeQuantity > 0 || obj.TestQuantity > 0
        || !string.IsNullOrEmpty(obj.LearningContent) || !string.IsNullOrEmpty(obj.RequestContent)
        || !string.IsNullOrEmpty(obj.Description) || !string.IsNullOrEmpty(obj.ContentFile));
}

private void SyncEditKeysToHidden()
{
    hidScheduleCheckingID.Value = this.ScheduleCheckingID.HasValue ? this.ScheduleCheckingID.Value.ToString() : "";
    hidClassSubjectID.Value = this.ClassSubjectID.HasValue ? this.ClassSubjectID.Value.ToString() : "";
    hidDate.Value = this.Date.HasValue ? this.Date.Value.ToString("yyyy-MM-dd HH:mm:ss") : "";
    hidSessionID.Value = this.SessionID.HasValue ? this.SessionID.Value.ToString() : "";
    hidTeacherID.Value = this.TeacherID ?? "";
}

private void ResolveEditKeysFromHidden()
{
    long lngTemp;
    if (long.TryParse(hidScheduleCheckingID.Value, out lngTemp) && lngTemp > 0)
        this.ScheduleCheckingID = lngTemp;

    if (long.TryParse(hidClassSubjectID.Value, out lngTemp) && lngTemp > 0)
        this.ClassSubjectID = lngTemp;

    int intTemp;
    if (int.TryParse(hidSessionID.Value, out intTemp))
        this.SessionID = intTemp;

    DateTime dtmTemp;
    if (DateTime.TryParse(hidDate.Value, out dtmTemp))
        this.Date = dtmTemp;

    if (!string.IsNullOrEmpty(hidTeacherID.Value))
        this.TeacherID = hidTeacherID.Value;
}

